import{_ as t,a}from"./chunks/public-page.Cis11Pa3.js";import{_ as r,c as s,o as n,a2 as i}from"./chunks/framework.PGES7OoM.js";const o="/assets/send-from-curvy.DRqgtrwp.png",f=JSON.parse('{"title":"Make Your Existing Assets Private","description":"","frontmatter":{"rawMarkdown":"# Make Your Existing Assets Private\\n\\nTo use Curvy for private payments, you first need to get some assets into your Curvy App.\\n\\nThis process is commonly referred to as \\"shielding\\", as Curvy shields your funds from prying eyes.\\n\\n## From the Curvy app\\n\\nThe easiest way to shield funds is to connect your existing wallet by clicking the *Fund from a connected wallet*\\nin the bottom right corner of the right sidebar in the Curvy App.\\n\\n![Send from Curvy](send-from-curvy.png)\\n\\n## From an ENS compatible wallet\\n\\nIf you are using a wallet that supports Ethereum Name Service, such as MetaMask or Rabby,\\nyou can just enter your Curvy ID as the recipient for a new transaction:\\n\\n![Using Curvy name in Metamask](ens-metamask.png)\\n\\n## Receiving from other wallets\\n\\nTo receive funds from other wallets, you can simply instruct the sender to open the following URL:\\n\\n```\\nhttps://your-curvy-id.curvy.name\\n```\\n\\nThis will create a one-time private receiving address to which they can send the funds.\\n\\nAn example with [https://travica.curvy.name](https://travica.curvy.name):\\n\\n![Public page](public-page.png)\\n","rawMarkdownPath":"/_raw/for-users/make-your-existing-assets-private.md","rawMarkdownTitle":"Make Your Existing Assets Private","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-users/make-your-existing-assets-private.md"},"headers":[],"relativePath":"for-users/make-your-existing-assets-private.md","filePath":"for-users/make-your-existing-assets-private.md","lastUpdated":1773768298000}'),p={name:"for-users/make-your-existing-assets-private.md"};function u(l,e,c,m,h,d){return n(),s("div",null,[...e[0]||(e[0]=[i("",15)])])}const g=r(p,[["render",u]])